command:
kubectl patch statefulset influx -n telemetry-3e02 --type merge -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "influx",
            "env": [
              {
                "name": "MODE",
                "value": "b"
              }
            ]
          }
        ]
      }
    }
  }
}'

cat > /tmp/patch.json << 'EOF'
{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "influx",
            "env": [
              {
                "name": "MODE",
                "value": "b"
              }
            ]
          }
        ]
      }
    }
  }
}
EOF
kubectl patch statefulset influx -n telemetry-3e02 --type merge -p "$(cat /tmp/patch.json)"

kubectl patch pvc data-influx-0 -n telemetry-3e02 --type merge -p '{
  "spec": {
    "resources": {
      "requests": {
        "storage": "128Mi"
      }
    }
  }
}'
